insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0233$t$, $t$Mahwah Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), now called Inspection Prior to Sale (IPS) on Township pages$t$, $j$["Issued by: Township of Mahwah Building Department (Construction Code Official)","Contact: Anthony Vero, Construction Code Official / Building Subcode · 201-529-5757 · avero@mahwahtwp.org","Apply: The code says CCOs are issued or denied within 10 days of filing the application. The code also requires the CCO before the property is listed.","How to apply: Fill in the Township's Inspection Prior to Sale form (owner, block and lot, realtor, phone, email) and return it with the $175 fee (check, e-check or charge) to the Building Department (Department of Inspections), 475 Corporate Drive, Mahwah, 201-529-5757. Check with the Health Department first that there are no septic, cesspool or well tank issues. The inspection is visual only.","Valid for: One year from the date of issuance, provided there is no material change in the physical status of the premises","Required for one- and two-family dwellings before the property is listed, and on transfer of title (homes with 3 or more units are exempt)","Visual inspection only (per the Inspection Prior to Sale form) by the Construction Code Official, who may call in subcode officials, the Water Department and the Department of Health","Check with the Health Department before applying that there are no septic system, cesspool or well tank issues","Inspection covers items such as pools, electric fixtures and wiring, plumbing fixtures and water heaters, heating and ventilation, the building exterior and other hazards","Any additions or construction done without permits must have permit fees paid before the CCO is issued","Separate smoke/CO certificate from Fire Prevention (not part of the CCO inspection)","Exempt transfers include deed corrections, transfers between spouses, parent and child or grandparent and grandchild, estate distributions, new construction and quitclaim deeds to quiet title","Also: Tax search notice: Tax searches and added assessment searches from the Tax Collector carry a notice that a CCO is required for a sale.","Also: Unpermitted work: If the CCO inspection finds additions or construction done without permits, the permit fees must be paid before the CCO is issued.","Also: Water Department and Health inspection: The CCO inspection may include the Water Department and the Department of Health.","Also: Health Department check (septic, cesspool, well): The Inspection Prior to Sale form asks sellers to check with the Health Department that there are no septic system, cesspool or well tank issues before applying."]$j$::jsonb, $j$[{"label":"Inspection Prior to Sale (CCO), residential","amount":"$175"}]$j$::jsonb, $t$https://www.mahwahtwp.org/DocumentCenter/View/9597/CCO-4-Inspection-Prior-to-Sale$t$, $t$https://www.mahwahtwp.org/159/Construction-Office-Department-of-Inspec$t$, $j$[{"url":"https://www.mahwahtwp.org/DocumentCenter/View/9597/CCO-4-Inspection-Prior-to-Sale","label":"Official source (mahwahtwp.org)"},{"url":"https://www.mahwahtwp.org/157/Fire-Prevention","label":"Official source (mahwahtwp.org)"},{"url":"https://ecode360.com/49703411","label":"Official source (ecode360.com)"},{"url":"https://www.mahwahtwp.org/159/Construction-Office-Department-of-Inspec","label":"Official source (mahwahtwp.org)"}]$j$::jsonb, $t$INSPECTION PRIOR TO SALE$t$, $t$1b871320c7a73add9ed18dd8d6c5f20afe78c2f16d55a691c24237aa4c4af0e9$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":21,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0233.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0233.json$t$, true),
  ($t$0233$t$, $t$Mahwah Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Mahwah Fire Prevention Bureau (Department of Fire Prevention) (town fire bureau)","Contact: Michael Roe, Fire Official (Fire Inspectors Ed Garza and Nick Kovacs, ext. 290) · 201-529-5757 ext. 275 · mroe@mahwahtwp.org","Apply: Contact the office or stop in to schedule once the application and affidavit are complete. If the change of occupant does not happen within 6 months, a new application is needed.","How to apply: Download the Mahwah Fire Prevention Smoke Inspection Packet (or pick one up at the Building Department), complete the application and affidavit, and return it with $90 cash or check payable to \"Township of Mahwah\" to Fire Prevention, 475 Corporate Drive. Then call or stop in to schedule the inspection.","Fire official in the NJ state directory (town), updated 7/22/2026: Michael R Roe · (201) 529-5757 · MRoe@mahwahtwp.org","Smoke detector on each level including basements (not attics or crawl spaces), and smoke and CO alarm outside each separate sleeping area within 10 feet of bedrooms","Homes built before January 1, 1977 may use 10-year lithium sealed battery smoke detectors; homes built on or after that date need hardwired detectors as originally required","The Township asks that hardwired detectors with removable batteries and detectors older than 10 years be replaced with hardwired 10-year sealed battery backup units; CO detectors replaced with 10-year sealed battery units","Low voltage monitored fire alarm systems must stay monitored and a copy of the alarm report must be included with the affidavit","Signed affidavit (Application and Certification) returned with the fee before the inspection","Portable fire extinguisher no longer required as of February 15, 2025 (the packet's form title still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance","amount":"$90"}]$j$::jsonb, $t$https://www.mahwahtwp.org/DocumentCenter/View/9113$t$, $t$https://www.mahwahtwp.org/157/Fire-Prevention$t$, $j$[{"url":"https://www.mahwahtwp.org/157/Fire-Prevention","label":"Official source (mahwahtwp.org)"},{"url":"https://www.mahwahtwp.org/DocumentCenter/View/9113","label":"Official source (mahwahtwp.org)"},{"url":"https://ecode360.com/34810979","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Another task performed by Fire Prevention is the certification of the operation of smoke detectors required by the State of New Jersey when a home is sold or there is a change of tenant.$t$, $t$66688ecf746ae9dba58bafc80ea7b94cefddc3aee82833167af0b58b21794392$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":21,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0233.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0233.json$t$, true),
  ($t$0242$t$, $t$Oakland Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval for Occupancy (CAO), formerly called CCO$t$, $j$["Issued by: Borough of Oakland Fire Prevention Bureau / Code Enforcement Department, with Board of Health, Building Department and Code Enforcement sign-offs","Contact: 201-337-8111 ext. 2025 · fireassistant@oakland-nj.gov","Apply: Submit at least 30 days before closing; can be filed as soon as the house has a buyer","How to apply: Apply online with the Borough's \"Residential CAO\" GovPilot form (linked on the Fire Prevention page), or fill out the PDF Application for Certificate of Approval for Occupancy (CAO) and Fire Certificate and return it to the Fire Prevention office, 1 Municipal Plaza, Oakland. An online application is not complete or processed until payment is received; pay by exact cash or check payable to the Borough of Oakland (the packet says 'Oakland Borough'). Submit at least 30 days before closing. Choose whether the CAO is mailed, emailed or picked up.","Valid for: The application is valid for 6 months from the application date; approvals expire 90 days from the signature date. After the fire certificate is issued the applicant has 90 days to complete the CAO ($30 for a 30-day extension).","Complete application (owner, buyer or realtor), with a secondary mailing address, phone and email for the buyer and phone and email for the seller","All open building permits and property maintenance violations must be closed before the CAO (and before a fire inspection can be set up)","Board of Health sign-off: septic reports, sewer information, well water reports; cesspools must be upgraded at realty transfer","Fire certificate (smoke alarms, CO alarms, fire extinguisher, house numbers)","Building inspection only if the fire inspector sees a construction code concern (for example water heater and boiler relief pipes within 6 inches of the floor, holes in garage ceiling, extension cords used as permanent wiring)","Also: Board of Health sign-off (septic, cesspool, sewer, well): The application goes to the Board of Health, which must sign off before the CAO. It reviews septic reports, sewer information and well water reports. Cesspools must be upgraded at realty transfer (2012 septic code), and homes on a well need a Private Well Testing Act test at realty transfer with results sent to health@oakland-nj.org and septics@co.bergen.nj.us.","Also: Open permits and property maintenance violations: All building permits and property maintenance violations must be closed before the fire inspection and before the CAO is issued."]$j$::jsonb, $j$[{"label":"Certificate of Approval for Occupancy, sale of single or two family home (includes realtor sign fee and Board of Health review fee)","amount":"$115"},{"label":"CAO extension, 30 days","amount":"$30"}]$j$::jsonb, $t$https://www.govpilot.com/forms/main/8ba7ec97-ae8/CAO-Residential/Borough-of-Oakland/NJ/7004/0$t$, $t$https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an$t$, $j$[{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1122/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Application-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1123/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Informational-Packet-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/1246/Fire-Prevention","label":"Official source (oakland-nj.gov)"},{"url":"https://www.govpilot.com/forms/main/8ba7ec97-ae8/CAO-Residential/Borough-of-Oakland/NJ/7004/0","label":"Official source (govpilot.com)"},{"url":"https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an","label":"Official source (oakland-nj.gov)"},{"url":"https://ecode360.com/35188097","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF APPROVAL FOR OCCUPANCY (CAO) AND FIRE CERTIFICATE FOR RESALE OF A SINGLE AND TWO FAMILY DWELLING$t$, $t$b8e189b474aa5204c441bb50f0a55f96dc84f3e3ea057198026cd265109ad07f$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":17,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0242.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0242.json$t$, true),
  ($t$0242$t$, $t$Oakland Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Oakland Fire Prevention Bureau (town fire bureau)","Contact: Denny Knubel, Fire Official · 201-337-8111 ext. 2025 · fireassistant@oakland-nj.gov","Apply: Apply at least 30 days before closing (same application as the CAO). An expedite fee is available. The office is open Monday to Friday, 8 am to 4 pm.","How to apply: Use the combined CAO and Fire Certificate application (the Residential CAO GovPilot form or the PDF) and pay by exact cash or check payable to the Borough of Oakland. The office schedules the fire inspection once open permits and violations are cleared.","Fire official in the NJ state directory, updated 2/18/2026: Denny G Knubel · (201) 337-8111 · fireofficial@oakland-nj.org","Smoke detectors on each level, including the basement, and within 10 feet of each separate sleeping area; hardwired or 10-year sealed battery; any detector older than 10 years must be replaced","Hardwired alarms from original construction stay hardwired (no battery-only replacement)","Carbon monoxide detectors within 10 feet of each separate sleeping area (battery, hardwired or plug-in, UL 2034)","Low voltage (monitored) alarm systems not part of original construction must have been tested in the year of sale with an NFPA 72 report","One fire extinguisher, 2A:10B:C, no more than 10 lbs, within 10 feet of the kitchen in the exit path, top no more than 5 feet above the floor, serviced and tagged in the past 12 months or with a recent purchase receipt (form still lists it)","House numbers in a contrasting color, 3 inches high, permanently affixed and clearly visible near the front door","All building permits and property maintenance violations closed before the fire inspection is scheduled","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire certificate, sale of single or two family home","amount":"$85"},{"label":"Expedite fee","amount":"$50"},{"label":"Re-inspection fee","amount":"$50"}]$j$::jsonb, $t$https://www.govpilot.com/forms/main/8ba7ec97-ae8/CAO-Residential/Borough-of-Oakland/NJ/7004/0$t$, $t$https://www.oakland-nj.gov/1246/Fire-Prevention$t$, $j$[{"url":"https://www.oakland-nj.gov/1246/Fire-Prevention","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1123/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Informational-Packet-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://www.govpilot.com/forms/main/8ba7ec97-ae8/CAO-Residential/Borough-of-Oakland/NJ/7004/0","label":"Official source (govpilot.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an","label":"Official source (oakland-nj.gov)"}]$j$::jsonb, $t$The Fire Prevention office is open Monday through Friday from 8 am to 4 pm.$t$, $t$3cb422088c084eb2b254191e0f8948a2b0dfc418651699aeb607466ba3a59a9d$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":18,"q_ok":17,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0242.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0242.json$t$, true),
  ($t$0601$t$, $t$Bridgeton$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Property Compliance (CPC)$t$, $j$["Issued by: Department of Housing, Code Enforcement & Rent Leveling (Code Enforcement Office)","Contact: Danielle Deitz, Housing Supervisor · 856-455-3230 Ext. 223 · DeitzD@cityofbridgeton.com","Apply: The fee depends on how early the request is received: more than 10 business days before closing for the lowest fee. Request the inspection before the date of sale.","How to apply: Fill out the Application for Certificate of Property Compliance (check 'Seller' and 'SALE APPLICATION', give the buyer and agent details) and file it with the Code Enforcement Office, City Hall, 181 E Commerce Street, Bridgeton, NJ 08302. Call 856-455-3230 (Housing Supervisor ext. 223, Housing Office Clerk ext. 217) to confirm the fee and schedule the inspection.","Inspection under the 2015 International Property Maintenance Code (the City's checklist is a general guide, not a full list)","Clean yard, grass and weeds under 10 inches, no rat infestation, sound accessory structures","House number at least 4 inches high","Sound foundation, walls, roof, gutters, chimney, porches, stairs and decks","Windows and doors in good repair and weather tight; screens from April 15 to October 15","Interior surfaces sanitary with no peeling or loose paint or plaster; railings and guards where required","Working plumbing with no leaks; water heater installed right with relief valve and discharge pipe","Heat of at least 65 degrees from October 1 to May 15; fuel-burning appliances vented outside","At least 60 amp electric service, 2 outlets per habitable room, GFCI outlet in bathroom and laundry, cover plates on all outlets","Exit doors and windows openable from inside without keys (no double-keyed deadbolts)","One fire extinguisher within 10 feet of the kitchen (on the 2021 checklist)","Smoke detectors on every level, in every bedroom and in the hall outside sleeping areas; CO detectors within 10 feet of all bedrooms","Also: Final water meter reading: The City charges for a final meter reading by how early it is requested: $35 more than 10 business days before closing, $70 for 4 to 10 business days, $125 for fewer than 4 business days (City Code 149-35H). The fee is paid with the final water bill."]$j$::jsonb, $j$[{"label":"Resale Certificate of Property Compliance / inspection, request received more than 10 business days before closing (City Code 149-20A(1))","amount":"$35"},{"label":"Request received 4 to 10 business days before closing (City Code 149-20A(2))","amount":"$70"},{"label":"Request received fewer than 4 business days before closing (City Code 149-20A(3))","amount":"$125"},{"label":"Each additional re-inspection (one re-inspection is included in the base fee)","amount":"$40"}]$j$::jsonb, $t$https://www.cityofbridgetonnj.gov/DocumentCenter/View/996/Certificate-of-Property-Compliance-Application-PDF$t$, $t$https://www.cityofbridgetonnj.gov/187/Housing-Code-Enforcement-Rent-Leveling$t$, $j$[{"url":"https://www.cityofbridgetonnj.gov/187/Housing-Code-Enforcement-Rent-Leveling","label":"Official source (cityofbridgetonnj.gov)"},{"url":"https://ecode360.com/31436751","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/6903833","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/46784552","label":"Official source (ecode360.com)"},{"url":"https://www.cityofbridgetonnj.gov/DocumentCenter/View/996/Certificate-of-Property-Compliance-Application-PDF","label":"Official source (cityofbridgetonnj.gov)"},{"url":"https://www.cityofbridgetonnj.gov/DocumentCenter/View/214/Inspection-Checklist-2022-PDF","label":"Official source (cityofbridgetonnj.gov)"}]$j$::jsonb, $t$Resale Certificates Upon the sale of any property within the City of Bridgeton, a resale CPC needs to be filled out and filed with the Code Enforcement Office.$t$, $t$f7089a91f1d9658dec237a6db7b05d20535d393f87f07dac40d5c41d0ded2117$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":26,"q_ok":24,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0601.json$t$, true),
  ($t$0601$t$, $t$Bridgeton$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Bridgeton City as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 1/12/2026: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://www.bridgetonfire.com/department","label":"Official source (bridgetonfire.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$ccfe33af39908acc108a952121b56279be7f0682b1358ee56043cd26d9a131e2$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":26,"q_ok":24,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0601.json$t$, true),
  ($t$0602$t$, $t$Commercial Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO)$t$, $j$["Issued by: Construction / Code Enforcement Office (Housing and Zoning Officer)","Contact: William White, Construction Official, Housing and Zoning Officer (also Plumbing Inspector) · 856-785-3100, ext. 320","How to apply: Call the Construction Office at 856-785-3100 ext. 320 to set up the inspection. Fill out the Application for Continued Certificate of Occupancy (block and lot, owner, seller's agent and buyer's agent) and pay at the time of application by cash, check or money order payable to 'Commercial Township'. Township offices are at 1768 Main Street, Port Norris.","Handrails on stairs with 3 or more risers; guardrails on porches or decks 30 inches or higher","No broken windows or doors; all must work","Switch plates and outlet covers in place; light fixtures with shades and no bare wires","No holes in walls or other structural damage; no exterior damage or roof leaks","Smoke detector on every level, within 10 feet of bedroom doors and in every bedroom","Carbon monoxide detector in the hallway within 10 feet of bedroom doors","Mounted ABC fire extinguisher within 10 feet of the kitchen (2017 list)","Breaker panel wired with no missing breakers","Hot and cold running water, working toilet, working heater; water heater relief valve extension 2 to 6 inches from the floor","4-inch white post 3 feet tall by the driveway with 3-inch reflective house numbers on two sides","No trash, motor vehicles or debris in the yard; all utilities on at the time of inspection","Bathroom window or exhaust fan; GFCI outlets within 3 feet of sinks","No flaking paint or stains on interior finishes; no double-keyed deadbolts","Water certificate from the Cumberland County Health Department and a septic certification","Also: Water certificate: A Water Certificate from the Cumberland County Health Department is required for the CO.","Also: Septic certification: Listed as item 23 on the 2017 CCO requirements."]$j$::jsonb, $j$[{"label":"Continued Certificate of Occupancy inspection, resale","amount":"$75"},{"label":"Re-inspection","amount":"$40.00"},{"label":"Continued certificate of occupancy, residential (Township Code 131-3C(6), Uniform Construction Code fee schedule; differs from the $75 on the Township CCO form)","amount":"$168"}]$j$::jsonb, $t$https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf$t$, $t$https://web.archive.org/web/20250321045909/https://commercialtwp.com/government/departments/housing/$t$, $j$[{"url":"https://web.archive.org/web/20250321045909/https://commercialtwp.com/government/departments/housing/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260401042214/https://www.commercialtwp.com/contact-us","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20250614110704/https://commercialtwp.com/government/departments/construction/","label":"Official source (web.archive.org)"},{"url":"https://ecode360.com/12604594","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/12604595","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/42117233","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$When are they required? When any property is sold When there is a change in tenants How do I get a C.O.? Contact the Construction Office at 856-785-3100, ext. 320 There is a $75 fee, $40.00 reinspection fee$t$, $t$b9b9f768b06743f17b42d357c59d08dbed5e2f7a915eb1a49e817e2dedf38612$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":1,"fee_bad":0,"fee_unchecked":2,"quotes":18,"q_ok":8,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0602.json$t$, true),
  ($t$0602$t$, $t$Commercial Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Commercial Township Construction Official / Housing and Zoning Official (smoke detector certification on transfer, Township Code 175-13)","Contact: William White, Construction Official, Housing and Zoning Officer (also Plumbing Inspector) · 856-785-3100, ext. 320","How to apply: The Township Code says the smoke detector certification on a sale comes from the Township Construction Official or Housing/Zoning Official, and the Township's resale CCO inspection checks smoke detectors, CO detectors and a fire extinguisher. Call the Construction Office at 856-785-3100, ext. 320 to set up the CCO inspection and confirm that it covers the smoke/CO certification. The NJ DCA online smoke certificate portal does not list Commercial Township (marked smoke-certificate exempt).","Fire official in the NJ state directory (NJ DCA, state), updated 4/4/2025: Louis Kilmer · (609)633-6132","The Township's CCO checklist (2017) checks smoke detectors on every level, within 10 feet of bedroom doors and in every bedroom, a CO detector within 10 feet of bedroom doors, and a mounted ABC fire extinguisher within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf$t$, $t$https://web.archive.org/web/20250321045909/https://commercialtwp.com/government/departments/housing/$t$, $j$[{"url":"https://ecode360.com/12604594","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$The above certifications shall be obtained from the present Township Construction Official or Housing/Zoning Official on existing dwellings.$t$, $t$ae9428265fbbde8abc40f789d07b7bfbf081e4d5bcc49b24033fbeabb54a24c9$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":1,"fee_bad":0,"fee_unchecked":2,"quotes":18,"q_ok":8,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0602.json$t$, true),
  ($t$0603$t$, $t$Deerfield Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Deerfield Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Melissa Shinn, Zoning Official, Code Enforcement · (856) 455-3200 · zoning@deerfieldtownship.org","How to apply: No Township resale certificate is needed. The seller still needs the Fire Marshal's smoke detector / CO certificate (see fire section), and septic and well test results go to the Cumberland County Department of Health.","Also: Septic and well tests: Septic and well test results should be forwarded to the Cumberland County Department of Health."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://sites.google.com/view/deerfieldtownship/departments/zoning-code$t$, $j$[{"url":"https://sites.google.com/view/deerfieldtownship/departments/zoning-code","label":"Official source (sites.google.com)"},{"url":"https://sites.google.com/view/deerfieldtownship/departments/construction","label":"Official source (sites.google.com)"}]$j$::jsonb, $t$The Fire Marshal is required to inspect and issue a permit for the resale or rental of Deerfield Township property per state law. A resale is the private sale of a house to another person. Nothing is required from the township to sell your home or for the buyer to purchase a home. Other regulations (septic and well tests, etc) will still apply.$t$, $t$e48573ceab0aaa8c9e5ab968d756af06a5c02b2505b50ea03f08b09158a59530$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-11-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0603.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-11-04. Source: property/data/municipal-requirements/checked/0603.json$t$, true),
  ($t$0603$t$, $t$Deerfield Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Deerfield Township Fire Prevention Bureau (Fire Marshal) (town fire bureau)","Contact: Christopher Williams, Fire Marshal (Fire Official) · (856) 455-3200 · firemarshal@deerfieldtownship.org","Apply: The fee depends on how early the request is received: more than 10 business days before the change of occupant for the lowest fee. The certificate must be obtained before the sale is final.","How to apply: Pick up the Smoke Detector, Carbon Monoxide & Fire Extinguisher Application at the Township Building (736 Landis Avenue, Rosenhayn), complete it and return it with the fee so the Fire Marshal can arrange an in-person inspection. The page says to mail the notarized form to Deerfield Township Hall c/o Fire Marshal, PO Box 350, Rosenhayn, NJ 08352. Fees are $45, $90 or $161 depending on how many business days before the change of occupant the request is received (Township Code 93-8E).","Fire official in the NJ state directory, updated 6/4/2025: Christopher E Williams · (856) 455-3200 · firemarshal@deerfieldtownship.org","Approved and tested smoke detectors and carbon monoxide alarms, certified before the sale is final (Township Code 93-8)","The Fire Prevention Bureau no longer accepts the Certification in Lieu of Inspection; an in-person inspection by the Fire Marshal is required","Portable fire extinguisher (form still lists it: the Township's application is titled Smoke Detector, Carbon Monoxide & Fire Extinguisher Application, and Code 93-8E still names the certificate for it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate (CSACMAPFEC), request received more than 10 business days before the change of occupant (Township Code 93-8E(1))","amount":"$45"},{"label":"Request received 4 to 10 business days before the change of occupant (Township Code 93-8E(2))","amount":"$90"},{"label":"Request received fewer than 4 business days before the change of occupant (Township Code 93-8E(3))","amount":"$161"}]$j$::jsonb, null, $t$https://sites.google.com/view/deerfieldtownship/departments/fire-marshal$t$, $j$[{"url":"https://sites.google.com/view/deerfieldtownship/departments/fire-marshal","label":"Official source (sites.google.com)"},{"url":"https://ecode360.com/5054578","label":"Official source (ecode360.com)"},{"url":"https://sites.google.com/view/deerfieldtownship/officials","label":"Official source (sites.google.com)"},{"url":"https://sites.google.com/view/deerfieldtownship/contact","label":"Official source (sites.google.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Deerfield Township Fire Prevention Bureau will no longer be accepting the Certification in Lieu of Inspection. Residents will now return to the former procedure of obtaining the Smoke Detector, Carbon Monoxide & Fire Extinguisher Application available at the Township Building, completing the form and returning it with the appropriate fee so an in-person inspection can be arranged by the Fire Marshall.$t$, $t$9334e306013b9c944f9fbd0cc0944de522ca1e64739ad9300ab60dda37108330$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-11-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0603.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-11-04. Source: property/data/municipal-requirements/checked/0603.json$t$, true),
  ($t$0604$t$, $t$Downe Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (CO) for resale$t$, $j$["Issued by: Zoning Office (Zoning Officer)","Contact: Nicole Marlette, Zoning Officer · 856-447-3100 Ext. 103 · zoningdowne@comcast.net","Apply: Submit everything before the inspection can be scheduled; inspections are only on Thursdays, 9 AM to 12 PM. Do not schedule settlement until all items are submitted and approved.","How to apply: Before the inspection is scheduled, send to Downe Township, Attn: Zoning, 288 Main Street, Newport NJ 08345: (1) a septic certificate or septic waiver in the buyers' name, (2) a water certificate (Fortescue properties with public water are exempt), both from the Cumberland County Health Department, 309 Buck Street, Millville (856-327-7602), (3) the fire certificate from the City of Bridgeton Fire Department, (4) a $25 check payable to Downe Township and (5) the Certificate of Occupancy Application. The Zoning Office then calls to schedule the Thursday morning inspection. Buyers cannot move in until the CO is approved.","Handrails on stairs with 2 or more steps","Hot water relief valve extension 6 inches from the floor; appliances vented properly","Emergency exit if there is sleeping on a 3rd floor","Windows, screens, and interior and exterior doors in good condition","Working heating system, plumbing and water pressure; GFCI outlets near water","Ceilings, walls, floors and interior and exterior paint in good condition; sound roof","Exterior entrance lighting","Extermination, general clean up inside and out, and a garbage container","House number on the front of the house and a white 911 numbering post by the street (6 ft 4x4 post, 4 ft above ground, black numbers at least 4 inches or 3 inches if reflective, on both sides, near the driveway)","Also: Septic certificate or septic waiver: From the Cumberland County Health Department, in the buyers' name, before the CO inspection is scheduled (Ordinance 2021-10 accepts the County waiver).","Also: Water certificate: From the Cumberland County Health Department; Fortescue properties on public water are exempt.","Also: 911 numbering post: White 911 numbering post by the street per Ordinance 2024-06 is checked at the CO inspection."]$j$::jsonb, $j$[{"label":"CO inspection fee (check payable to Downe Township)","amount":"$25"},{"label":"CO re-inspection fee, if needed","amount":"$25"}]$j$::jsonb, $t$https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf$t$, $t$https://downetwpnj.org/departments/zoning-office/$t$, $j$[{"url":"https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/departments/zoning-office/","label":"Official source (downetwpnj.org)"}]$j$::jsonb, $t$Effective as of: Jan. 1, 2026 RE: CO INSPECTION - PROCESS & SCHEDULING REQUIRMENTS$t$, $t$9c572a10e98d4e7b616bb0dfcbef177855257299486065da4d3a3c8df4df679c$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":25,"q_ok":13,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0604.json$t$, true),
  ($t$0604$t$, $t$Downe Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Downe Township as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 5/18/2026: Jack Justice, Jr · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://downetwpnj.org/wp-content/uploads/docs/mayor/ordinances/2025/Ordinance-No_-2025-14-Fire-Prevention-Ordinance.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$08aa3f9b3457cf7894b69ce85d8985d18ae276204bd0a003453987365e5d0465$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":25,"q_ok":13,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0604.json$t$, true),
  ($t$0605$t$, $t$Fairfield Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Sales Inspection / Sales Registration)$t$, $j$["Issued by: Zoning Office / Housing (Code Enforcement / Housing Inspector)","Contact: Mark Benjamin, Code Enforcement / Housing Inspector · 856-451-9284 (ext. 309) · MarkB@fairfieldtownshipnj.org","Apply: The fee list warns there is a minimum waiting period to get a C/O on a previously owned home; the length is not stated.","How to apply: Fill out the Fairfield Township Sales Inspection Form (owner, real estate agent, new owner's name, house / apartment / trailer, number of bedrooms) and pay the $75 sales registration fee to the Zoning Office, 70 Fairton Gouldtown Road, Bridgeton (mail: P.O. Box 240, Fairton, NJ 08320). Water and septic certifications are checked. To schedule or for questions call 856-451-9284 (the form says ext. 304, 8:30 AM to 12:30 PM, Monday to Friday).","Smoke detectors present and working","Carbon monoxide detectors present and working","Fire extinguisher mounted (on the 2023 form)","Water certification and sewer (septic) certification","Heating certification","Windows open, lock and have sound glass; doors in good condition","Plumbing pipes and fixtures, water pressure, water heater relief valve with floor discharge","Appliance venting and exhaust fans","Handrails and a 911 numbering pole","Emergency exit from a 3rd floor","Interior surfaces and interior and exterior paint; basement and firewalls; roof and chimney; porches, decks, stairs and railings","No mice, rats or roaches; clean property with a trash container","Electric wiring, outlets and GFCI outlets","Repairs found at inspection must be done within 30 days","Also: Water and septic certifications: The sales inspection form checks water certification and sewer certification; the form's back page records water and septic certifications received.","Also: Heating certification: Listed as item 21 on the sales inspection form.","Also: Sewer connection on sale: Where a public sewer line runs in the street or easement in front of the home, the owner must connect to it no later than the sale or other transfer of title, and no certificate of occupancy is issued until the connection and fees are arranged and proof is given to the Township Clerk (Township Code 375-2)."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (sales form)","amount":"$75.00"},{"label":"Transfer of Ownership (listed separately on the same fee list; the page does not explain how it relates to the sales CCO)","amount":"$75.00"},{"label":"Sales registration fee, includes 1 initial inspection and 1 re-inspection","amount":"$75"},{"label":"Additional inspection after a failed re-inspection","amount":"$75"}]$j$::jsonb, $t$http://fairfieldtownshipnj.org/wp-content/uploads/2023/06/20230622124137835-2.pdf$t$, $t$http://fairfieldtownshipnj.org/departments/construction/rental-registration/$t$, $j$[{"url":"http://fairfieldtownshipnj.org/departments/construction/printed-material-fee-list/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/departments/construction/rental-registration/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/wp-content/uploads/2023/06/20230622124137835-2.pdf","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/wp-content/uploads/2022/11/NewSales23.pdf","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/about-fairfield/township-directory/","label":"Official source (fairfieldtownshipnj.org)"}]$j$::jsonb, $t$Transfer of Ownership $75.00 Certificate of Occupancy ( Click for RENTAL form ) $75.00 Certificate of Continued Occupancy ( Click for SALES form ) $75.00 Change of Occupancy $75.00$t$, $t$0844d4bf870f886c0968acb7f8ac9b46fe20383e719adfbb881d5703afa26ecb$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":25,"q_ok":20,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0605.json$t$, true),
  ($t$0605$t$, $t$Fairfield Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Fairfield Township as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 7/25/2024: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"https://ecode360.com/48097620","label":"Official source (ecode360.com)"},{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://fairfieldtownshipnj.org/departments/bureau-of-fire-protection/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detector and carbon monoxide alarm inspections, and issuance of certificates of approval, shall be performed by the Bridgeton Fire Prevention Bureau under the shared services agreement. Fees shall be as per the City of Bridgeton Code, as amended.$t$, $t$eebbe135e634b955b45754640b18e6e9d237eff576dd67a108c2da577bd19780$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":25,"q_ok":20,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0605.json$t$, true),
  ($t$0606$t$, $t$Greenwich Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (housing inspection)$t$, $j$["Issued by: Office of Housing & Zoning (Zoning / Code Enforcement Officer)","Contact: Neal Sheppard, Zoning / Code Enforcement Officer · (856) 455-8640 · zoning@historicgreenwichnj.org","How to apply: Fill out the Township's Application for Continued Certificate of Occupancy (owner, seller's agent, buyer's agent, owner's future address) and pay at the time of application by cash, check or money order payable to Greenwich Township. The Township building is not regularly staffed; mail to Greenwich Township, P.O. Box 64, Greenwich, NJ 08323, or contact the Zoning / Code Enforcement Officer. The fee amounts are blank on the posted form.","Remove trash and debris inside and out; cut high grass and weeds; no standing water","Walkways, steps and driveways free of tripping hazards; accessory structures sound","Pools clean with self-closing, self-latching gates","No more than one unregistered vehicle","Sound siding, roof, flashing, gutters, foundation, chimney and structural members; exterior wood and metal protected and painted","House and unit numbers visible from the street","Handrails on stairs with more than 4 risers; guardrails at least 30 inches high","Windows open and stay open, with screens and unbroken glass; exterior doors open from inside without a key","Interior surfaces free of peeling paint; privacy locks on bedroom and bathroom doors; bathroom window or exhaust fan; dryer vented outside","Plumbing, water heater (110 degrees, discharge pipe about 6 inches from the floor) and heating system in safe working order","Carbon monoxide detector outside the bedroom areas","Two outlets per habitable room; GFCI outlets within 6 feet of water, in bathrooms, laundry and outdoors","Proof of extermination if insects or rodents are found; wood stoves inspected by a licensed chimney inspector","Work done without permits must be permitted and finaled","Passing County Health Department water test and septic certification (or waiver), and a passing fire inspection report from the Bridgeton Fire Department","Also: Water test and septic certification: Passing water test certification and septic certification or waiver from the Cumberland County Health Department are required for the housing inspection.","Also: Open permits: Work done without permits must get permits and final inspections from the Construction Office.","Also: Historic district: Homes in the historic district must meet Greenwich Historic Preservation Commission requirements."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (Township Code 12-2.3)","amount":"$50.00"}]$j$::jsonb, $t$http://www.historicgreenwichnj.org/wp-content/uploads/2022/05/CO.pdf$t$, $t$https://www.historicgreenwichnj.org/planning-documents/$t$, $j$[{"url":"https://ecode360.com/36607599","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36607600","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36607601","label":"Official source (ecode360.com)"},{"url":"https://www.historicgreenwichnj.org/planning-documents/","label":"Official source (historicgreenwichnj.org)"},{"url":"http://www.historicgreenwichnj.org/wp-content/uploads/2022/05/CO.pdf","label":"Official source (historicgreenwichnj.org)"},{"url":"http://www.historicgreenwichnj.org/wp-content/uploads/2025/12/Common-Violations.pdf","label":"Official source (historicgreenwichnj.org)"},{"url":"https://www.historicgreenwichnj.org/municipal-directory/","label":"Official source (historicgreenwichnj.org)"}]$j$::jsonb, $t$No person shall sell or transfer any structure within the Township of Greenwich unless a Certificate of Continued Occupancy certifying that the structure is in compliance with all provisions of the current version of the International Property Maintenance Code, 2006 edition, and all other applicable ordinances of the Township of Greenwich has been issued.$t$, $t$7dbf246160ade06cb4ffaefd9cb0cb423636d1e1830f4993a5f774e66f2003f1$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":28,"q_ok":24,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0606.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0606.json$t$, true),
  ($t$0606$t$, $t$Greenwich Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Greenwich Township as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 5/18/2026: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"https://ecode360.com/36607478","label":"Official source (ecode360.com)"},{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.historicgreenwichnj.org/planning-documents/","label":"Official source (historicgreenwichnj.org)"},{"url":"https://www.historicgreenwichnj.org/municipal-directory/","label":"Official source (historicgreenwichnj.org)"},{"url":"https://www.historicgreenwichnj.org/fire-rescue/","label":"Official source (historicgreenwichnj.org)"}]$j$::jsonb, $t$Smoke detectors and carbon monoxide alarms shall be inspected by the Bridgeton Fire Prevention Bureau or its representative of the City of Bridgeton, and Certificates of Approval with respect to the operation thereof shall be issued by the same under the subject Shared Services Agreement.$t$, $t$d8dc4bff60efdd93ebbfe5963d38c7342ed911ea9667aefd20cda1a866388263$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":28,"q_ok":24,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0606.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0606.json$t$, true),
  ($t$0611$t$, $t$Shiloh Borough$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for a new occupant of an existing building (zoning permit first)$t$, $j$["Issued by: Borough of Shiloh (Housing Code Official: Upper Deerfield Township; zoning permit from the Borough Zoning Officer)","Contact: Teresa Warburton, Housing Code Official (Upper Deerfield Township, serving Shiloh) · 856-455-9591 · twarburton@upperdeerfield.com","How to apply: No resale application is posted. The 1999 ordinance says a zoning permit from the Zoning Officer must be issued before a certificate of occupancy goes to a new occupant of an existing building; the Borough's zoning permit form is at https://shilohborough.com/wp-content/uploads/2021/04/SHL_ZONING_PERMIT.pdf. Contact the Housing Code Official (Teresa Warburton, Upper Deerfield Township, 856-455-9591) or the Borough office (856-455-3054, clerk@shilohborough.com) to arrange the certificate of occupancy.","Also: Zoning permit before the certificate of occupancy: The 1999 ordinance requires a zoning permit from the Zoning Officer before a certificate of occupancy is issued to a new occupant ($10 in 1999)."]$j$::jsonb, $j$[{"label":"Certificate of occupancy, per dwelling unit (1999 Development Ordinance; certified check or bank money order payable to the Borough of Shiloh)","amount":"$25"},{"label":"Zoning permit, which must be issued before a certificate of occupancy for a new occupant (1999 Development Ordinance)","amount":"$10"}]$j$::jsonb, null, $t$https://shilohborough.com/government/other-officials/$t$, $j$[{"url":"https://shilohborough.com/wp-content/uploads/2020/10/Shiloh-Development-Ord-As-Amended-1999.pdf","label":"Official source (shilohborough.com)"},{"url":"https://shilohborough.com/government/other-officials/","label":"Official source (shilohborough.com)"},{"url":"https://shilohborough.com/wp-content/uploads/2025/02/SHL_REORG2025Agenda.pdf","label":"Official source (shilohborough.com)"},{"url":"https://upperdeerfield.com/administration/construction-code/","label":"Official source (upperdeerfield.com)"}]$j$::jsonb, $t$B. Requirement for Issuance of Zoning Permit Prior to Other Permits. A zoning permit shall be issued by the Zoning Officer before the issuance of either a certificate of occupancy to a new occupant of an existing building or portion of an existing building or portion of an existing building, or before the issuance of a building permit.$t$, $t$a8b29dbdf049a7fd7bfd5ca2f05abc989c9994002d2532c0d384b883d97bde3f$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0611.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0611.json$t$, true),
  ($t$0611$t$, $t$Shiloh Borough$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department, City of Bridgeton Fire Department · 856-451-0091 · firedepartment@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page and pick Shiloh Borough as the municipality. Payment is by check or money order payable to the City of Bridgeton Fire Department, due at or before the inspection (the form says an online payment link will be on the invoice). The certificate is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 (guideline sheet) / (856) 451-0091 (Bureau of Fire Prevention).","Fire official in the NJ state directory, updated 4/30/2026: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"},{"label":"Re-inspection for a failed or no-show inspection: same fee as the initial inspection tier ($45.00, $90.00 or $161.00)","amount":"$45.00 to $161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://forms.gle/oWLh33S1kuggYuRQ8","label":"Official source (forms.gle)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$31501bd92ccc216f73d2ccea3dab92bc38f341cc0e9b88f66f4d9ee38f8d66ff$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":19,"q_ok":16,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0611.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0611.json$t$, true),
  ($t$0612$t$, $t$Stow Creek Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (sale property)$t$, $j$["Issued by: Stow Creek Township Office of Housing and Zoning (Housing Officer)","Contact: Neal Sheppard, Housing Officer and Zoning Officer · 856-455-8640 · Zoninghousing@stowcreektwp.org","How to apply: Fill out the Township's Certificate of Occupancy Application (check 'Sale Property', give owner, buyer and agent details) and mail it with the $50.00 check to Stow Creek Township, Attn: Zoning/Housing Department, PO Box 308, Shiloh, NJ 08353. Also email copies of the application and check to the Zoning Officer (Zoninghousing@stowcreektwp.org). Inspections must be completed and passed before occupancy or before personal items are placed in the home.","Remove trash and debris inside and out; cut high grass and weeds; fix tripping hazards on walks, steps and driveways","Sheds, garages, fences and pools kept sound; pool gates self-closing and self-latching","Exterior walls, siding, roof, gutters, foundation and chimney in good repair; scrape and paint peeling paint","House numbers visible from the street, plus a 3 foot white 911 post at the end of the driveway with numbers on the left, right and street sides","Handrails on stairs with more than 4 risers; guardrails at least 30 inches high","Windows open easily and stay open, no broken glass, tight-fitting screens; exterior doors open from inside without a key","Bedroom and bathroom privacy locks; bathroom window or exhaust fan; dryer vented outside","Plumbing working and sanitary; water heater gives at least 110 degree water and has a discharge pipe about 6 inches from the floor","Heating system safe; fuel-burning appliances clear of combustibles; electrical safe and workmanlike","At least two outlets in every habitable room; grounded outlets in bathrooms and laundry; GFCI outlets within 6 feet of water and outdoors","Carbon monoxide detector outside the bedroom areas","Work done without permits must be permitted and finaled","Proof of extermination if insects or rodents are found","Also: Fire inspection report from the Bridgeton Fire Department: The Township's housing inspection list says a passing fire inspection report is required from the Bridgeton Fire Department.","Also: Septic certification or waiver: If there is a septic system, a passing certification or waiver from the County Health Department is required.","Also: Water certificate: A passing water certificate from the County Health Department is required.","Also: Chimney inspection for wood stoves: If there is a wood burning stove, a passing inspection report from a licensed chimney contractor or inspector is required.","Also: Open or missing construction permits: Work done without building permits must be permitted and final inspections completed (Upper Deerfield construction office)."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy application (sale property or rental unit)","amount":"$50.00"}]$j$::jsonb, $t$https://stowcreektwp.org/wp-content/uploads/2025/10/SC-CO-Application-2025.pdf$t$, $t$https://stowcreektwp.org/planning-zoning-and-housing/$t$, $j$[{"url":"https://stowcreektwp.org/wp-content/uploads/2025/01/Stow-Creek-Township-Land-Development-Ordinance-2025.pdf","label":"Official source (stowcreektwp.org)"},{"url":"https://stowcreektwp.org/wp-content/uploads/2025/10/SC-CO-Application-2025.pdf","label":"Official source (stowcreektwp.org)"},{"url":"https://stowcreektwp.org/planning-zoning-and-housing/","label":"Official source (stowcreektwp.org)"},{"url":"https://stowcreektwp.org/wp-content/uploads/2025/10/Common-Violations-1-2.pdf","label":"Official source (stowcreektwp.org)"}]$j$::jsonb, $t$D. A certificate of occupancy shall be required in any of the following circumstances:$t$, $t$ecfbbf250a62a56d32878a976eff76f19264cfa1444813d5804069f9a1bf2dcb$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":20,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0612.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0612.json$t$, true),
  ($t$0612$t$, $t$Stow Creek Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department, City of Bridgeton Fire Department · 856-451-0091 · firedepartment@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page and pick Stow Creek Township as the municipality. Payment is by check or money order payable to the City of Bridgeton Fire Department, due at or before the inspection (the form says an online payment link will be on the invoice). The certificate is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 (guideline sheet) / (856) 451-0091 (Bureau of Fire Prevention).","Fire official in the NJ state directory, updated 4/30/2026: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"},{"label":"Re-inspection for a failed or no-show inspection: same fee as the initial inspection tier ($45.00, $90.00 or $161.00)","amount":"$45.00 to $161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://forms.gle/oWLh33S1kuggYuRQ8","label":"Official source (forms.gle)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$f0e0cec8e6023d62351e8ccd5d8288067b5b2a879859e3b2455b3aa996a5690f$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":22,"q_ok":20,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0612.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0612.json$t$, true),
  ($t$0613$t$, $t$Upper Deerfield Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy on sale$t$, $j$["Issued by: Upper Deerfield Township (Housing Officer and Fire Marshal inspections)","Contact: Anthony Lamanteer, Jr., Township Housing Officer (also Zoning Officer) · 856-455-9591 · tlamanteer@upperdeerfield.com","Apply: Request the inspection 5 or more business days before closing for the lower fee","How to apply: No application form is posted online. Contact the Housing Officer (Anthony Lamanteer, Jr., tlamanteer@upperdeerfield.com, 856-455-9591; office hours Monday, Tuesday and Thursday 8:30 to 4:30) at the Municipal Building, 1325 Highway 77, Seabrook, NJ 08302, to request the certificate of occupancy inspection before closing."]$j$::jsonb, $j$[{"label":"Residential (single family, apartment, townhouse, mobile home or other dwelling unit), request received 5 or more business days before closing (Ordinance 892, adopted September 17, 2026)","amount":"$100"},{"label":"Residential, request received 4 or fewer business days before closing (Ordinance 892, adopted September 17, 2026)","amount":"$150"}]$j$::jsonb, null, $t$https://upperdeerfield.com/administration/housing-zoning/$t$, $j$[{"url":"https://upperdeerfield.com/wp-content/uploads/2026/09/ORD-892-Amending-Certificate-of-Occupancy.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://ecode360.com/14804477","label":"Official source (ecode360.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/09/ORD-892-final-Notice-Amending-Certificate-of-Occupancy.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2023/06/21-66-Continued-Certificate-of-Occupancy-Based-on-Seller-Self-Inspection-Copy.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/03/02-19-2026-Short-Minutes.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/03/02-05-2026-Short-Minutes.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/01/26-44-Appointing-Housing-Officer.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/administration/housing-zoning/","label":"Official source (upperdeerfield.com)"}]$j$::jsonb, $t$Every application for a review and issuance of a certificate of occupancy as stipulated in § 303-6 of this chapter shall be accompanied by the fees normally required in connection with:$t$, $t$a9fa71755b1f8d3c5cf74c005e1ad7a7c937437fb14d077a6ee975943d156b10$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0613.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0613.json$t$, true),
  ($t$0613$t$, $t$Upper Deerfield Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Upper Deerfield Township Fire Safety (Fire Marshal) (town fire bureau)","Contact: Chris Williams, Fire Inspector/Fire Marshal (Fire Safety Official, Director) · 856-455-9591 · cwilliams@upperdeerfield.com","Apply: Request 5 or more business days before closing for the lower Certificate of Occupancy fee","How to apply: The smoke/CO check is done with the Township Certificate of Occupancy inspection; arrange it through the Housing Officer (856-455-9591, tlamanteer@upperdeerfield.com). Fire Safety office: Chris Williams, 856-455-9591 or 856-451-3811 Ext. 143, cwilliams@upperdeerfield.com.","Fire official in the NJ state directory (town), updated 12/19/2022: Christopher Williams · (856) 455-9591 · cwilliams@upperdeerfield.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined Township Certificate of Occupancy inspection, 5 or more business days before closing (the Township says the CO fee covers the housing and Fire Marshal certifications)","amount":"$100"},{"label":"Combined Township Certificate of Occupancy inspection, 4 or fewer business days before closing (same note)","amount":"$150"}]$j$::jsonb, null, $t$https://upperdeerfield.com/public-safety/fire-safety/$t$, $j$[{"url":"https://upperdeerfield.com/public-safety/fire-safety/","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/administration/directory-of-officials/","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/03/02-19-2026-Short-Minutes.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2023/06/21-66-Continued-Certificate-of-Occupancy-Based-on-Seller-Self-Inspection-Copy.pdf","label":"Official source (upperdeerfield.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://upperdeerfield.com/wp-content/uploads/2026/09/ORD-892-Amending-Certificate-of-Occupancy.pdf","label":"Official source (upperdeerfield.com)"}]$j$::jsonb, $t$Fire Safety Official Chris Williams, Director Manuel Aquilar, Deputy Phone: 856-451-3811 Ext. 143$t$, $t$40f184e873e66d79a1bed9564e2c26db64058f5d238ad4941bcdc02fc0325eee$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":14,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0613.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0613.json$t$, true),
  ($t$1210$t$, $t$Middlesex Borough$t$, $t$MIDDLESEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Application for Sale/Re-Rent, Residential)$t$, $j$["Issued by: Office of the Construction Official / Department of Code Enforcement and Zoning","Contact: Karen Wick, Technical Assistant, Construction office (application header); Matthew Dillingham, Director of Code Enforcement and… · 732-356-7400 ext. 247 · construction@middlesexboro-nj.gov","How to apply: Download the Borough's Resale / Re-Rent packet from the Forms page. Return pages 1 and 2 (the Application for Sale/Re-Rent and the Zoning Dept Residence File) and the last page (Middlesex Borough Police Department form with the new buyer's information) with a check payable to Middlesex Borough for $125 to the Office of the Construction Official, 1200 Mountain Avenue, Middlesex, NJ 08846. The smoke/CO inspection form (Section 3) goes separately to the Middlesex County Fire Marshal (firemarshal@co.middlesex.nj.us); the Borough does not accept that form or its payment.","Smoke alarm on each floor, including the basement, within 10 feet of all sleeping areas (the Borough sheet says alarms must be within 7 years of the manufacture date)","CO alarm within 10 feet of all sleeping areas, outside the rooms","Fire extinguisher mounted within 10 feet of the kitchen, ABC type, 2.5 to 10 pounds","Running water, working electric service and at least one flushable toilet","Handrails and guards on steps of 3 or more risers or 30 inches","Well water and/or septic report from the Board of Health, if applicable","Water heater grounded (jump bonded); relief discharge tube not reduced and ending within 6 inches of the floor","Solid aluminum dryer vent pipe, not flex pipe","Anti-tilt device on the stove","House numbers visible from the street","Exit doors open from inside without a key or special knowledge","No mold or water damage","Any outstanding Borough fines or liens paid in full","New owner's Middlesex Resident Info (Police Department emergency file) form must be brought to the Construction office before inspections are scheduled; photographs may be taken","Change of title only (vacant, not yet habitable home): floor plan layout of all floors","Property is subject to Ordinance 317-11 (property maintenance)","Also: Police Department resident emergency file / alarm registration form: The resale packet's last pages are a Middlesex Borough Police Department 'Resident Emergency File/Alarm Registration Form' that must be returned with the new buyer's information. It notes an initial $25.00 registration fee for residential alarms, paid to the Police Department.","Also: Zoning Department residence file: Page 2 of the packet is a Zoning Department 'Residence File' with the new buyer's name, mailing address, phone, email and the use of the property; it is returned with the application.","Also: Outstanding fines or liens: The Borough's resale checklist says any outstanding fines or liens must be paid in full before the certificate is issued."]$j$::jsonb, $j$[{"label":"Residential Sale / Re-Rent inspection, per dwelling unit","amount":"$125.00"},{"label":"Reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.middlesexboro-nj.gov/s/Resale-Re-Rent-Application.pdf$t$, $t$https://www.middlesexboro-nj.gov/zoningcode-enforcement$t$, $j$[{"url":"https://www.middlesexboro-nj.gov/construction","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/forms","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/s/Resale-Re-Rent-Application.pdf","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/zoningcode-enforcement","label":"Official source (middlesexboro-nj.gov)"}]$j$::jsonb, $t$When selling a residential home, the actual CO needed is a Residential Resale Certificate.$t$, $t$1bfcbb0c462f54dd61d88e3a6e83d551984267ceb1199eaa178a533d1dc71c87$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":22,"q_ok":7,"q_bad":0,"q_unchecked":15},"source":"property/data/municipal-requirements/checked/1210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1210.json$t$, true),
  ($t$1210$t$, $t$Middlesex Borough$t$, $t$MIDDLESEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Middlesex County Fire Marshal's Office","Contact: Michael Gallagher, Fire Official (Middlesex County Fire Marshal) · 732-316-7171 · mike.gallagher@co.middlesex.nj.us","Apply: Apply 10 or more business days before closing for the lowest County fee. The certificate is issued at the inspection and is valid for 6 months.","How to apply: Complete Section 3 of the Borough packet (the Middlesex County Fire Marshal 'Smoke & Carbon Monoxide Detector Application') and send it to the County Fire Marshal, not the Borough; the Borough's instructions say to email it to firemarshal@co.middlesex.nj.us. Middlesex County Fire Marshal, 1001 Fire Academy Drive, Sayreville, NJ 08879, phone 732-316-7171. Checks are payable to the Office of the Fire Marshal.","Fire official in the NJ state directory (county fire marshal), updated 2/6/2026: Michael Gallagher · (732) 316-7174 · mike.gallagher@co.middlesex.nj.us","County letter: smoke alarms on every level (basement, first and second floors, not crawl spaces or unfinished attics) and within 10 feet of sleeping rooms; no older than 10 years or the maker's expiration date","County letter: CO alarm outside each separate sleeping area; no older than 5 years or the maker's expiration date (other County pages say 7 years for stand-alone CO alarms)","County letter: house numbers at least 4 inches high, visible from the street and in a contrasting color (2 inches if on both sides of a curbside mailbox)","County letter: smoke/CO alarms, house numbers and fire extinguisher must all comply; certificate is issued at the inspection and valid for 6 months","Smoke alarms within 10 feet of every bedroom and at least one on every floor, including finished and unfinished basements (not needed in an unfinished attic)","Smoke alarms may not be more than 10 years old; stand-alone CO alarms not more than 7 years old; combination alarms not more than 10 years old","A hard-wired smoke alarm must be replaced with a hard-wired alarm","A replacement battery smoke alarm must have a sealed 10-year lithium battery","Fire extinguisher (listed on the County form in the Borough's 2026 packet): 2-A:10-B:C, about 5 pounds, wall-mounted on the way out of the kitchen, no higher than 5 feet, with a receipt or NJ licensed contractor tag from the past 12 months","Homes built 1984 or later need interconnected electric alarms; homes built 1990 or later also need battery backup and an alarm in each bedroom","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"County smoke/CO inspection, 10 or more business days before closing","amount":"$50.00"},{"label":"County smoke/CO inspection, less than 10 business days before closing","amount":"$75.00"},{"label":"County smoke/CO inspection, less than 4 business days before closing","amount":"$125.00"},{"label":"Reinspection after a failed inspection","amount":"$20.00"},{"label":"Not present for a scheduled inspection without notice","amount":"$75.00"},{"label":"Smoke/CO certificate fee on the County's 2020 self-inspection affidavit form (archived copy)","amount":"$50"}]$j$::jsonb, $t$https://www.middlesexboro-nj.gov/s/Resale-Re-Rent-Application.pdf$t$, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.middlesexboro-nj.gov/s/Resale-Re-Rent-Application.pdf","label":"Official source (middlesexboro-nj.gov)"},{"url":"https://web.archive.org/web/20201128112400/http://www.middlesexcountynj.gov/Government/Departments/PSH/Documents/Fire-Marshal/Residential%20Smoke%20Detector%20and%20Carbon%20Monoxide%20Inspection%20Info%20and%20Application.pdf","label":"Official source (web.archive.org)"},{"url":"https://www.southrivernj.org/DocumentCenter/View/856/Smoke-Detector--Carbon-Monoxide-Detector-Inspection-PDF","label":"Official source (southrivernj.org)"}]$j$::jsonb, $t$C Middlesex Borough$t$, $t$935054074f250acccbb2e3f08a0cbff8d134e1c9955e67ae64de6db17c09c97f$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":22,"q_ok":7,"q_bad":0,"q_unchecked":15},"source":"property/data/municipal-requirements/checked/1210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/1210.json$t$, true),
  ($t$1714$t$, $t$Upper Pittsgrove Township$t$, $t$SALEM$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC), also called Certificate of Occupancy; Pre-Occupancy Inspection for sales$t$, $j$["Issued by: Zoning Office / Housing Office (Zoning & Housing Official)","Contact: Andy Hoglen, Zoning & Housing Official · 856-358-8500 · zoningofficer@upperpittsgrovenj.org","How to apply: Fill in the Upper Pittsgrove Township Pre-Occupancy Application, SALES Only (revised 03/30/2026) and mail it with a check payable to Upper Pittsgrove Township to the Township Housing Office, or bring it to the Municipal Building, 431 Route 77, Elmer. The Smoke/CO alarms inspection is a separate $25.00 application to the Bureau of Fire Prevention. Zoning Office hours are now Wednesday 10 a.m. to 12 p.m.","House numbers 5 inches high and visible from the street","GFI protected outlets within 6 feet of a water source and on all exterior outlets","Fire extinguisher mounted in the kitchen","Appliances installed properly and working, no extension cords; exhaust fan over the stove (ductless hood allowed) and anti-tip bracket on the stove","Adequate electric, heating and plumbing service; two separate outlets in each habitable room","Bathroom vented or with a working window","Screened window in each room; all windows working with locks; exterior doors and hardware working","Handrails on steps with more than 3 risers; rails around landings or porches 30 inches or higher","Water heater relief valve piped to within 6 inches of the floor; emergency shut-off at the top of the stairs for a basement heater","Pools over 125 square feet and 3 feet or higher need a fence at least 4 feet high with a self-latching gate","House free of insect infestation","Smoke/CO inspection must pass (separate Bureau of Fire Prevention certificate)","Private well homes must comply with the Private Well Testing Act before sale; homes on a cesspool or privy cannot be sold until it is replaced with an approved system","Also: Private well testing: Under the Private Well Testing Act (N.J.S.A. 58:12A-26), a home on a private well cannot be sold without complying with the Act.","Also: Cesspool or privy: N.J.A.C. 7:9A-3.16 bars the sale of a property served by a cesspool, privy, outhouse or pit toilet until it is replaced with an approved system."]$j$::jsonb, $j$[{"label":"Pre-Occupancy Inspection, sales","amount":"$25"},{"label":"Re-inspection (if needed)","amount":"$25"}]$j$::jsonb, $t$https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf$t$, $t$https://upperpittsgrovenj.org/zoning-and-construction/$t$, $j$[{"url":"https://upperpittsgrovenj.org/zoning-and-construction/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/CO-Inspection-Checklist.pdf","label":"Official source (upperpittsgrovenj.org)"}]$j$::jsonb, $t$UPT ordinance requires a COC (Certificate of Compliance) on residential or commercial rental properties whenever occupants change; therefore, a new COC is also required prior to the sale of a property.$t$, $t$d0028d10d0da5c206b3156091c620353b7ac2180a55e57b18eae07c03e089863$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":18,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1714.json$t$, true),
  ($t$1714$t$, $t$Upper Pittsgrove Township$t$, $t$SALEM$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Upper Pittsgrove Bureau of Fire Prevention (town fire bureau)","Contact: Tim O'Donnell, Smoke/CO Alarms Inspector on the Township page; Fire & Safety Official (Fire Official in the state fire directory) · 856-358-8500 · upperpittsgrovefm@outlook.com","Apply: Payment is due at the time of the inspection. No lead time or validity period is published.","How to apply: Fill in the Township Bureau of Fire Prevention Smoke and Carbon Monoxide Alarms Inspection Application (revised 2026, posted October 2026) with the owner, applicant and realtor details. Pay $25.00 at the time of the inspection by exact cash, check or money order payable to Upper Pittsgrove Township Bureau of Fire Prevention. Questions go to upperpittsgrovefm@outlook.com or 856-358-8500.","Fire official in the NJ state directory (town), updated 4/7/2025: Timothy J O'Donnell · (856) 358-8500","10-year sealed battery alarms or hardwired alarms on every level of the dwelling; an alarm at the bottom of the basement stairwell at ceiling level","Alarms in the hallways within 10 feet of all bedrooms, and a smoke alarm in every bedroom","Smoke and CO alarms must be UL listed, less than 10 years old, working and installed per the maker's instructions; plug-in, battery or hardwired alarms are allowed, but hardwired alarms cannot be replaced with battery alarms","Do not plug alarms into switched outlets or outlets at the floor molding","A low-voltage fire alarm system must be tested and approved by an alarm contractor before the inspection; show the alarm certification to the inspector","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar, a generator or battery storage need a permanent printed label (wording like \"Caution: Multiple Sources of Power\") at the main electrical panel and the electric meter","The Township Housing CO checklist (separate from this form) still lists a fire extinguisher mounted in the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide alarms inspection application","amount":"$25.00"},{"label":"Re-inspection for a failed or no-show inspection (same as the initial inspection fee)","amount":"$25.00"}]$j$::jsonb, $t$https://upperpittsgrovenj.org/wp-content/uploads/2026/10/Alarms-Inspection-Application-and-Guidelines.pdf$t$, $t$https://upperpittsgrovenj.org/zoning-and-construction/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/10/Alarms-Inspection-Application-and-Guidelines.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/zoning-and-construction/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/emergency-services/","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://upperpittsgrovenj.org/wp-content/uploads/2026/03/Pre-Occupancy-SALES-Application.pdf","label":"Official source (upperpittsgrovenj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$M Upper Pittsgrove Township$t$, $t$77930654a737c85957c141ef8e694ee15922ab7919ed94f8c3902fa38d792551$t$, $t$2026-11-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-11-03","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":18,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-11-03 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/1714.json$t$, true)
